338:     function _validate(string memory contractName, Options memory opts, bool requireReference) private {
339:         if (opts.unsafeSkipAllChecks) {
340:             return;
341:         }
342: 
343:         string[] memory inputs = buildValidateCommand(contractName, opts, requireReference);
344:         Vm.FfiResult memory result = Utils.runAsBashCommand(inputs);
345:         string memory stdout = string(result.stdout);
