347:         // CLI validate command uses exit code to indicate if the validation passed or failed.
348:         // As an extra precaution, we also check stdout for "SUCCESS" to ensure it actually ran.
349:         if (result.exitCode == 0 && stdout.toSlice().contains("SUCCESS".toSlice())) {
350:             return;
351:         } else if (result.stderr.length > 0) {
352:             // Validations failed to run
353:             revert(string(abi.encodePacked("Failed to run upgrade safety validation: ", string(result.stderr))));
354:         } else {
355:             // Validations ran but some contracts were not upgrade safe
356:             revert(string(abi.encodePacked("Upgrade safety validation failed:\n", stdout)));
357:         }
