361:         string memory contractName,
362:         Options memory opts,
363:         bool requireReference
364:     ) internal view returns (string[] memory) {
365:         string memory outDir = Utils.getOutDir();
366: 
367:         string[] memory inputBuilder = new string[](2 ** 16);
368: 
369:         uint16 i = 0;
370: 
371:         inputBuilder[i++] = "npx";
372:         inputBuilder[i++] = string(abi.encodePacked("@openzeppelin/upgrades-core@", Versions.UPGRADES_CORE));
