392:         }
393: 
394:         for (uint8 j = 0; j < opts.exclude.length; j++) {
395:             string memory exclude = opts.exclude[j];
396:             if (bytes(exclude).length != 0) {
397:                 inputBuilder[i++] = "--exclude";
398:                 inputBuilder[i++] = string(abi.encodePacked('"', exclude, '"'));
399:             }
