406:         }
407: 
408:         if (bytes(opts.unsafeAllow).length != 0) {
409:             inputBuilder[i++] = "--unsafeAllow";
410:             inputBuilder[i++] = opts.unsafeAllow;
411:         }
412: 
413:         if (opts.unsafeAllowRenames) {
414:             inputBuilder[i++] = "--unsafeAllowRenames";
415:         }
416: 
417:         // Create a copy of inputs but with the correct length
418:         string[] memory inputs = new string[](i);
419:         for (uint16 j = 0; j < i; j++) {
420:             inputs[j] = inputBuilder[j];
421:         }
422: 
423:         return inputs;
