438:     function _deploy(string memory contractName, bytes memory constructorData) private returns (address) {
439:         bytes memory creationCode = Vm(Utils.CHEATCODE_ADDRESS).getCode(contractName);
440:         address deployedAddress = _deployFromBytecode(abi.encodePacked(creationCode, constructorData));
441:         if (deployedAddress == address(0)) {
442:             revert(
443:                 string(
444:                     abi.encodePacked(
445:                         "Failed to deploy contract ",
446:                         contractName,
447:                         ' using constructor data "',
448:                         string(constructorData),
449:                         '"'
450:                     )
451:                 )
452:             );
453:         }
454:         return deployedAddress;
455:     }
