"-exec grep -l \",\n                sourceCodeHash,\n                \" {} +\"\n            )\n        );\n\n        Vm.FfiResult memory result = runAsBashCommand(inputs);\n        string memory output = string(result.stdout);\n\n        if (!strings.toSlice(output).endsWith(\".json\".toSlice())) {\n            revert(\n                string(\n                    abi.encodePacked(\n                        \"Could not find build-info file for contract '\",\n                        contractName,\n                        \"' with source code hash \",\n                        sourceCodeHash\n                    )\n                )\n            );\n        }\n\n        return output;\n    }\n\n    /**\n     * @notice Retrieves the output directory for Foundry, with a fallback to the default directory if not specified.\n     *\n     * @return The output directory path as a string.\n     */\n    function getOutDir() internal view returns (string memory) {\n        Vm vm = Vm(CHEATCODE_ADDRESS);\n\n        string memory defaultOutDir = \"out\";\n\n        try vm.envString(\"FOUNDRY_OUT\") returns (string memory outDir) {\n            return outDir;\n        } catch {\n            return defaultOutDir;\n        }\n    }\n\n    /**\n     * @notice Splits a string slice into an array of strings based on a delimiter slice.\n     */\n    function _split(\n        strings.slice memory inputSlice,\n        strings.slice memory delimSlice\n    ) private pure returns (string[] memory) {\n        uint256 numParts = strings.count(inputSlice, delimSlice) + 1;\n\n        string[] memory parts = new string[](numParts);\n\n        for (uint256 i = 0; i < numParts; i++) {\n            strings.slice memory token = strings.split(inputSlice, delimSlice);\n            parts[i] = strings.toString(token);\n        }\n\n        return parts;\n    }\n\n    /**\n     * @notice Converts a contract name string into a valid file name format.\n     *\n     * @param contractName The input contract name string to be converted.\n     * @return string The formatted file name.\n     */\n    function _toFileName(string memory contractName) private pure returns (string memory) {\n        strings.slice memory s = strings.toSlice(contractName);\n\n        if (strings.toSlice(contractName).endsWith(\".sol\".toSlice())) {\n            return contractName;\n        }\n\n        if (strings.toSlice(contractName).contains(\":\".toSlice())) {\n            strings.slice memory copy = strings.copy(strings.toSlice(contractName));\n            strings.slice memory token = strings.split(copy, \":\".toSlice());\n            return strings.toString(token);\n        }\n\n        if (strings.toSlice(contractName).endsWith(\".json\".toSlice())) {\n            string[] memory parts = _split(strings.toSlice(contractName), \"/\".toSlice());\n\n            if (parts.length > 1) {\n                return parts[parts.length - 2];\n            }\n        }\n\n        revert(\n            string(\n                abi.encodePacked(\n                    \"Invalid contract name '\",\n                    contractName,\n                    \"'. Expected format: MyContract.sol or MyContract.sol:MyContract or path/to/MyContract.json\"\n                )\n            )\n        );\n    }\n\n    /**\n     * @notice Converts a contract name string into a short name by removing file extensions and paths.\n     *\n     * @param contractName The full contract name string to be shortened.\n     * @return The shortened contract name.\n     */\n    function _toShortName(string memory contractName) private pure returns (string memory) {\n        strings.slice memory s = strings.toSlice(contractName);\n\n        if (strings.toSlice(contractName).endsWith(\".sol\".toSlice())) {\n            return strings.toString(\n                strings.until(strings.copy(strings.toSlice(contractName)), \".sol\".toSlice())\n            );\n        }\n\n        if (strings.toSlice(contractName).contains(\":\".toSlice())) {\n  