ts.\n     */\n    function runAsBashCommand(string[] memory inputs) internal returns (Vm.FfiResult memory) {\n        Vm vm = Vm(CHEATCODE_ADDRESS);\n\n        string memory bashPath;\n        try vm.envString(\"OPENZEPPELIN_BASH_PATH\") returns (string memory path) {\n            bashPath = path;\n        } catch {\n            bashPath = \"bash\";\n        }\n\n        string[] memory command = toBashCommand(inputs, bashPath);\n\n        Vm.FfiResult memory result = vm.tryFfi(command);\n\n        if (result.exitCode != 0 && result.stdout.length == 0 && result.stderr.length == 0) {\n            revert(\n                string(\n                    abi.encodePacked(\n                        \"Failed to execute bash command. Make sure bash is installed and available in your PATH, \",\n                        \"or set the OPENZEPPELIN_BASH_PATH environment variable to the path of your bash executable.\"\n                    )\n                )\n            );\n        }\n\n        return result;\n    }\n}\n"
