ing (or mnenomic file path)\n320:     /// at the derivation path `m/44'/60'/0'/0/{index}`.\n321:     function deriveKey(string calldata mnemonic, uint32 index) external pure returns (uint256 privateKey);\n322: \n323:     /// Derive a private key from a provided mnenomic string (or mnenomic file path)\n324:     /// at `{derivationPath}{index}`.\n325:     function deriveKey(string calldata mnemonic, string calldata derivationPath, uint32 index)\n326:         external\n327:         pure\n328:         returns (uint256 privateKey);\n329: \n330:     /// Derive a private key from a provided mnenomic string (or mnenomic file path) in the specified language\n331:     /// at the derivation path `m/44'/60'/0'/0/{index}`.\n332:     function deriveKey(string calldata mnemonic, uint32 index, string calldata language)\n333:         external\n334:         pure\n335:         returns (uint256 privateKey);\n336: \n337:     /// Derive a private key from a provided mnenomic string (or mnenomic file path) in the specified language\n338:     /// at `{derivationPath}{index}`.\n339:     function deriveKey(string calldata mnemonic, string calldata derivationPath, uint32 index, string calldata language)\n340:         external\n341:         pure\n342:         returns (uint256 privateKey);\n343: \n344:     /// Derives secp256r1 public key from the provided `privateKey`.\n345:     function publicKeyP256(uint256 privateKey) external pure returns (uint256 publicKeyX, uint256 publicKeyY);\n346: \n347:     /// Adds a private key to the local forge wallet and returns the address.\n348:     function rememberKey(uint256 privateKey) external returns (address keyAddr);\n349: \n350:     /// Derive a set number of wallets from a mnemonic at the derivation path `m/44'/60'/0'/0/{0..count}`.\n351:     /// The respective private keys are saved to the local forge wallet for later use and their addresses are returned.\n352:     function rememberKeys(string calldata mnemonic, string calldata derivationPath, uint3