les.\n570:     function setEnv(string calldata name, string calldata value) external;\n571: \n572:     // ======== EVM ========\n573: \n574:     /// Gets all accessed reads and write slot from a `vm.record` session, for a given address.\n575:     function accesses(address target) external returns (bytes32[] memory readSlots, bytes32[] memory writeSlots);\n576: \n577:     /// Gets the address for a given private key.\n578:     function addr(uint256 privateKey) external pure returns (address keyAddr);\n579: \n580:     /// Gets all the logs according to specified filter.\n581:     function eth_getLogs(uint256 fromBlock, uint256 toBlock, address target, bytes32[] calldata topics)\n582:         external\n583:         returns (EthGetLogs[] memory logs);\n584: \n585:     /// Gets the current `block.blobbasefee`.\n586:     /// You should use this instead of `block.blobbasefee` if you use `vm.blobBaseFee`, as `block.blobbasefee` is assumed to be constant across a transaction,\n587:     /// and as a result will get optimized out by the compiler.\n588:     /// See https://github.com/foundry-rs/foundry/issues/6180\n589:     function getBlobBaseFee() external view returns (uint256 blobBaseFee);\n590: \n591:     /// Gets the current `block.number`.\n592:     /// You should use this instead of `block.number` if you use `vm.roll`, as `block.number` is assumed to be constant across a transaction,\n593:     /// and as a result will get optimized out by the compiler.\n594:     /// See https://github.com/foundry-rs/foundry/issues/6180\n595:     function getBlockNumber() external view returns (uint256 height);\n596: \n597:     /// Gets the current `block.timestamp`.\n598:     /// You should use this instead of `block.timestamp` if you use `vm.warp`, as `block.timestamp` is assumed to be constant across a transaction,\n599:     /// and as a result will get optimized out by the compiler.\n600:     /// See https://github.com/foundry-rs/foundry/issues/6180\n601:     function getBlockTimesta